import {useEffect,useState} from 'preact/hooks';
import {Button,Notice,Field} from '../../components/ui.jsx';
import {compareDraft} from '../work/issue-draft.js';
import {DraftDecision} from '../work/issue-draft.jsx';
export function useAdminDraft(scope,record,fields) {
  const values=record=>Object.fromEntries(fields.map(key=>[key,record?.[key]??'']));
  const [saved,setSaved]=useState({scope,base:null,mine:values(null),latest:null});
  const state=saved.scope===scope?saved:{scope,base:null,mine:values(null),latest:null};
  const dirty=state.base?compareDraft(values(state.base),state.mine,values(state.base)).dirty:false;
  useEffect(()=>{
    if(!record)return;
    setSaved(previous=>{
      if(previous.scope!==scope||!previous.base)return {scope,base:record,mine:values(record),latest:null};
      if(previous.base.revision===record.revision)return previous;
      if(compareDraft(values(previous.base),previous.mine,values(previous.base)).dirty)return {...previous,latest:record};
      return {scope,base:record,mine:values(record),latest:null};
    });
  },[scope,record?.revision]);
  function accept(latest,mine=values(latest)){setSaved({scope,base:latest,mine,latest:null});}
  return {...state,dirty,setValues:mine=>setSaved({...state,mine}),accept,
    body:()=>({...state.mine,expectedRevision:state.base?.revision}),
    decision:{before:values(state.base),mine:state.mine,current:values(state.latest),latest:state.latest}};
}
export function AdminDraftDecision({draft,error,reload,busy}) {
  const conflict=error??(draft.latest?{status:409,message:'A newer saved version is available. Your local draft is retained.'}:null);
  const lost=[401,403,404].includes(error?.status);
  return <>{lost&&<fieldset disabled><legend>Retained local draft after access loss</legend>{Object.entries(draft.mine).map(([key,value])=><Field label={'Retained '+key} value={value} readOnly/>)}</fieldset>}<p>{draft.dirty?'You have unsaved local changes.':'This draft matches the saved version.'}</p>
    <Button type="button" disabled={busy} onClick={reload}>Inspect latest version</Button>
    {draft.latest&&!error&&<Notice>A newer saved version is waiting for your decision.</Notice>}
    <DraftDecision error={conflict} {...draft.decision} busy={busy} onLoad={latest=>draft.accept(latest)} onApply={(latest,mine)=>draft.accept(latest,mine)}/>
  </>;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createServer} from 'node:http';
import {once} from 'node:events';
import {build} from 'esbuild';
import {testServer} from '../../server/test/helpers.js';
async function python(settings){
  let child;
  try{return await new Promise((resolve,reject)=>{
    child=spawn('/usr/bin/python3',[fileURLToPath(new URL('./people-admin-browser.py',import.meta.url)),JSON.stringify(settings)],{detached:true});let stdout='',stderr='';
    const timer=setTimeout(()=>{try{process.kill(-child.pid,'SIGKILL');}catch{}reject(new Error('People browser exceeded 55 seconds'));},55000);
    child.stdout.on('data',value=>stdout+=value);child.stderr.on('data',value=>stderr+=value);
    child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);resolve({code,stdout,stderr});});
  });}finally{if(child?.pid){try{process.kill(-child.pid,'SIGKILL');}catch{}}}
}
for(const mode of ['access','drafts','audit'])test('pinned browser people administration '+mode,{timeout:65000},async()=>{
  const server=await testServer();
  try{
    const api=server.agent(),auth=await api('POST','/auth/signup',{name:'Browser owner',email:'people-browser@admin.test',password:'correct-horse-battery'});
    const guest=server.agent(),guestAuth=await guest('POST','/auth/signup',{name:'Browser guest',email:'people-guest@admin.test',password:'correct-horse-battery'});
    const org=(await api('POST','/orgs',{name:'Browser administration'})).data.organization;
    const other=(await api('POST','/orgs',{name:'Other browser organization'})).data.organization;
    await api('POST','/orgs/'+org.id+'/members',{userId:guestAuth.data.user.id,role:'guest'});
    const project=(await api('POST','/orgs/'+org.id+'/projects',{key:'BROWSE',name:'Original project'})).data.project;
    const insert=server.ctx.db.prepare('INSERT INTO projects (id,org_id,key,name,description,archived,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)');
    for(let n=0;n<220;n++)insert.run('browser-project-'+n,org.id,'PAGE'+String(n).padStart(3,'0'),'Browser project '+n,'',n===219?1:0,server.ctx.now(),server.ctx.now());
    const team=(await api('POST','/orgs/'+org.id+'/teams',{name:'Browser team',description:'Before description'})).data.team;
    const result=await python({mode,url:server.url,cookie:auth.cookie,orgId:org.id,otherOrgId:other.id,userId:guestAuth.data.user.id,teamId:team.id,projectId:project.id});
    assert.equal(result.code,0,result.stderr+'\n'+result.stdout);assert.equal(JSON.parse(result.stdout.trim()).ok,true);
    if(mode==='access'){assert.equal((await api('GET','/orgs/'+org.id+'/members/'+guestAuth.data.user.id+'/access')).data.membership.role,'guest');assert.equal((await guest('GET','/projects/'+project.id)).status,403);}
    if(mode==='drafts'){const saved=(await api('GET','/teams/'+team.id)).data.team;assert.equal(saved.name,'My chosen team');assert.equal(saved.description,'Peer description');}
  }finally{await server.close();}
});
test('pinned browser people action duplicate opaque-resource unmount and first-render paging custody',{timeout:65000},async()=>{
  const bundle=await build({entryPoints:[fileURLToPath(new URL('./people-harness.jsx',import.meta.url))],bundle:true,write:false,format:'iife',jsxFactory:'h'});
  const server=createServer((req,res)=>{res.setHeader('content-type',req.url==='/bundle.js'?'text/javascript':'text/html');res.end(req.url==='/bundle.js'?bundle.outputFiles[0].text:'<div id="app"></div><script src="/bundle.js"></script>');});server.listen(0,'127.0.0.1');await once(server,'listening');
  try{const result=await python({mode:'lifetime',url:'http://127.0.0.1:'+server.address().port});assert.equal(result.code,0,result.stderr+'\n'+result.stdout);assert.equal(JSON.parse(result.stdout.trim()).ok,true);}
  finally{server.closeAllConnections();await new Promise(resolve=>server.close(resolve));}
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {auditQuery,auditChanges,auditValue,emptyAuditFilters} from '../src/pages/people/audit-state.js';
test('audit date draft accepts exact UTC and rejects local or reversed windows',()=>{
  assert.equal(auditQuery({...emptyAuditFilters(),from:'2026-10-16T00:00:00Z'}).from,'2026-10-16T00:00:00.000Z');
  assert.throws(()=>auditQuery({from:'2026-10-16T00:00:00+08:00'}),/exact UTC/);
  assert.throws(()=>auditQuery({from:'2026-10-17T00:00:00Z',to:'2026-10-16T00:00:00Z'}),/before/);
});
test('audit field comparison presents only recorded changes with distinct cleared and absent values',()=>{
  const result=auditChanges({before:{role:'guest',name:'Same',scopes:['org:read']},after:{role:'member',name:'Same',scopes:[],revokedAt:null}});
  assert.deepEqual(result.map(item=>item.key),['role','scopes','revokedAt']);
  assert.equal(auditValue(result[2].before),'Not recorded');assert.equal(auditValue(result[2].after),'Cleared');assert.equal(auditValue([]),'None');assert.equal(auditValue(false),'No');
});

import {h,render} from 'preact';
import {useState} from 'preact/hooks';
import {useAction,usePaged} from '../src/pages/people/forms.jsx';
const proof=window.proof={calls:[],effects:[],signals:[],reads:[],completions:[],resolvers:[]};
const fakeApi={get(path){proof.reads.push(path);return new Promise(resolve=>proof.resolvers.push({path,resolve}));}};
function Owned({scope}){
  const action=useAction(value=>proof.effects.push([scope,value]),scope);
  window.run=()=>action.run(signal=>{proof.calls.push(scope);proof.signals.push(signal);return new Promise((resolve,reject)=>{proof.resolve=resolve;proof.reject=reject;});},'Saved '+scope,value=>proof.completions.push([scope,value]));
  window.double=()=>{window.run();window.run();};
  window.cancelled=()=>proof.signals.map(signal=>signal.aborted);
  return <p id="action-state">{scope} {action.busy?'busy':'idle'} {action.message} {action.error?.message}</p>;
}
function Paging({scope}){
  const page=usePaged(fakeApi,'/'+scope,1);
  window.next=page.next;
  return <p id="page-state">{scope} Page {page.number} {page.loading?'loading':page.items.map(item=>item.id).join(',')}</p>;
}
function Harness(){
  const [scope,setScope]=useState('organization-a'),[visible,setVisible]=useState(true);
  window.scope=value=>setScope(value);window.unmount=()=>setVisible(false);
  return <>{visible&&<Owned scope={scope}/>}<Paging scope={scope}/></>;
}
render(<Harness/>,document.getElementById('app'));
